struct KeyHeap {
    a: Vec<u128>,
}

impl KeyHeap {
    fn with_capacity(c: usize) -> Self {
        KeyHeap {
            a: Vec::with_capacity(c),
        }
    }

    #[inline(always)]
    fn clear(&mut self) {
        self.a.clear();
    }

    #[inline(always)]
    fn push(&mut self, x: u128) {
        let mut i = self.a.len();
        self.a.push(x);
        let p = self.a.as_mut_ptr();
        unsafe {
            while i > 0 {
                let up = (i - 1) >> 1;
                let y = *p.add(up);
                if y >= x {
                    break;
                }
                *p.add(i) = y;
                i = up;
            }
            *p.add(i) = x;
        }
    }

    #[inline(always)]
    fn pop(&mut self) -> Option<u128> {
        let last = self.a.pop()?;
        let n = self.a.len();
        if n == 0 {
            return Some(last);
        }
        let p = self.a.as_mut_ptr();
        unsafe {
            *p.add(n) = 0;
            let top = *p;
            let mut i = 0usize;
            loop {
                let c = 2 * i + 1;
                if c >= n {
                    break;
                }
                let l = *p.add(c);
                let r = *p.add(c + 1);
                let (m, mv) = if r > l { (c + 1, r) } else { (c, l) };
                if mv <= last {
                    break;
                }
                *p.add(i) = mv;
                i = m;
            }
            *p.add(i) = last;
            Some(top)
        }
    }
}

