                    dp_table[current_weight] = potential_value;
                    track_selection[i][current_weight] = true;
                }
            }

            if dp_table[capacity] >= target_value {
                break;
            }
        }

        if dp_table[capacity] < target_value {
            return Ok(None);
        }

        let mut selected_items = Vec::new();
        let mut remaining_capacity = capacity;
