//! Exact bounded exchanges. Every candidate retains its original ordinal.
//! The quadratic interactions must be nonnegative, as in the TIG generator.

#[derive(Clone, Copy, Debug)]
pub(super) struct Group {
    pub ids: [usize; 3],
    pub len: usize,
    pub weight: i64,
    pub value: i64,
    pub ordinal: usize,
}

pub(super) fn groups<W, C, Q>(
    items: &[usize],
    count: usize,
    weight: W,
    value: C,
    q: Q,
    add: bool,
) -> Vec<Group>
where
    W: Fn(usize) -> i64,
    C: Fn(usize) -> i64,
    Q: Fn(usize, usize) -> i64,
{
    let mut out = Vec::new();
    for (i, &a) in items.iter().enumerate() {
        if count == 1 {
            out.push(Group {
                ids: [a, 0, 0],
                len: 1,
                weight: weight(a),
                value: value(a),
                ordinal: out.len(),
            });
            continue;
        }
        for (j, &b) in items.iter().enumerate().skip(i + 1) {
            let pair = value(a) + value(b) + if add { q(a, b) } else { -q(a, b) };
            let pair_weight = weight(a) + weight(b);
            if count == 2 {
                out.push(Group {
                    ids: [a, b, 0],
                    len: 2,
                    weight: pair_weight,
                    value: pair,
                    ordinal: out.len(),
                });
            } else {
                for &c in &items[j + 1..] {
                    let extra = q(a, c) + q(b, c);
                    out.push(Group {
                        ids: [a, b, c],
                        len: 3,
                        weight: pair_weight + weight(c),
                        value: pair + value(c) + if add { extra } else { -extra },
                        ordinal: out.len(),
                    });
                }
            }
        }
    }
    out
}

