const K: usize = 64;

fn mix(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    let mut x = *state;
    x = (x ^ (x >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    x ^ (x >> 31)
}

struct Graph {
    m: usize,
    he_off: Vec<u32>,
    he_nodes: Vec<u32>,
    nd_off: Vec<u32>,
    nd_edges: Vec<u32>,
}

fn km1(g: &Graph, part: &[u8]) -> u64 {
    let mut total = 0u64;
    for e in 0..g.m {
        let mut f = 0u64;
        for &v in &g.he_nodes[g.he_off[e] as usize..g.he_off[e + 1] as usize] {
            f |= 1u64 << part[v as usize];
        }
        total += f.count_ones() as u64 - 1;
    }
    total
}

fn affinity(g: &Graph, part: &[i32]) -> Vec<f64> {
    let mut w = vec![0f64; K * K];
    let mut bs = [0usize; K];
    for e in 0..g.m {
        let mut f = 0u64;
        for &v in &g.he_nodes[g.he_off[e] as usize..g.he_off[e + 1] as usize] {
            f |= 1u64 << part[v as usize];
        }
        let lam = f.count_ones() as usize;
        if lam < 2 {
            continue;
        }
        let x = 1.0 / (lam - 1) as f64;
        let mut c = 0;
        for b in 0..K {
            if f >> b & 1 == 1 {
                bs[c] = b;
                c += 1;
            }
        }
        for i in 0..c {
            for j in i + 1..c {
                w[bs[i] * K + bs[j]] += x;
                w[bs[j] * K + bs[i]] += x;
            }
        }
    }
    w
}

fn bisect(w: &[f64], set: &[usize], rng: &mut u64, children: &mut Vec<[usize; 2]>) -> usize {
    if set.len() == 1 {
        return set[0];
    }
    let h = set.len() / 2;
    let mut best_cut = f64::INFINITY;
    let mut best: Vec<usize> = Vec::new();
    for _ in 0..30 {
        let mut perm = set.to_vec();
        for i in (1..perm.len()).rev() {
            let j = (mix(rng) % (i as u64 + 1)) as usize;
            perm.swap(i, j);
        }
        let mut side = [false; K];
        for &x in &perm[..h] {
            side[x] = true;
        }
        loop {
            let mut d = [0f64; K];
            for &x in set {
                for &y in set {
                    if x != y {
                        d[x] += if side[x] != side[y] { w[x * K + y] } else { -w[x * K + y] };
                    }
                }
            }
            let mut gain = 1e-12;
            let mut pick = None;
            for &x in set {
                if !side[x] {
                    continue;
                }
                for &y in set {
                    if side[y] {
                        continue;
                    }
                    let gxy = d[x] + d[y] - 2.0 * w[x * K + y];
                    if gxy > gain {
                        gain = gxy;
                        pick = Some((x, y));
                    }
                }
            }
            match pick {
                Some((x, y)) => {
                    side[x] = false;
                    side[y] = true;
                }
                None => break,
            }
        }
        let mut cut = 0.0;
        for &x in set {
            for &y in set {
                if side[x] && !side[y] {
                    cut += w[x * K + y];
                }
            }
        }
        if cut < best_cut {
            best_cut = cut;
            best = set.iter().copied().filter(|&x| side[x]).collect();
        }
    }
    let rest: Vec<usize> = set.iter().copied().filter(|x| !best.contains(x)).collect();
    let a = bisect(w, &best, rng, children);
    let b = bisect(w, &rest, rng, children);
    children.push([a, b]);
    K + children.len() - 1
}

