impl LoadBias {
    fn build(der: &Der) -> Self {
        let mut machine = 0;
        let mut load = f64::NEG_INFINITY;
        for (m, &w) in der.machine_load0.iter().enumerate() {
            if w > load {
                load = w;
                machine = m;
            }
        }
        let share = (load / der.avg_machine_load).clamp(1.0, 4.0);
        Self { machine, share }
    }
